    Source = fnLoadTable(
        "dim_diagnosis",
        "select (d.icd_version::text || '-' || d.icd_code) as diagnosis_key, d.* from marts.dim_diagnosis d where exists (select 1 from marts.fact_diagnoses f where f.icd_code = d.icd_code and f.icd_version = d.icd_version) order by d.icd_version, d.icd_code",
