// ------------------------------------------------------------ slicer_dimension tables

// Query: dim_age_group
// Grain: one row per age_group (with sort order). Source: derived. Rows at export: 4.
// Note: distinct values of fact_admissions/fact_readmissions.age_group
let
    Source = fnLoadTable(
        "dim_age_group",
        "select age_group, case age_group when '<18' then 1 when '18-44' then 2 when '45-64' then 3 when '65-79' then 4 when '80+' then 5 else 99 end as age_group_order from ( select age_group from marts.fact_admissions where age_group is not null union select age_group from marts.fact_readmissions where age_group is not null) v order by 2, 1",
        {
        {"age_group", type text},
        {"age_group_order", Int64.Type}
        },
        {}
    )
in
    Source

// Query: dim_insurance
// Grain: one row per insurance value. Source: derived. Rows at export: 3.
// Note: distinct values of fact_admissions/fact_readmissions.insurance
let
    Source = fnLoadTable(
        "dim_insurance",
        "select insurance from ( select insurance from marts.fact_admissions where insurance is not null union select insurance from marts.fact_readmissions where insurance is not null) v order by 1, 1",
        {
        {"insurance", type text}
        },
        {}
    )
in
    Source

